-- Narrow staging runtime admission grants no school population or object retrieval authority.
begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
select ok(has_function_privilege('cuevo_api','internal.synthetic_school_runtime_allowed(uuid)','EXECUTE'),'API has only a purpose-limited synthetic admission check');
select ok(not has_function_privilege('cuevo_api','internal.require_synthetic_intelligence_school(uuid)','EXECUTE'),'Existing raw population precondition remains private');
select ok(not has_function_privilege('anon','internal.synthetic_school_runtime_allowed(uuid)','EXECUTE'),'Anonymous Data API cannot inspect synthetic admission');
select ok(not has_function_privilege('authenticated','internal.synthetic_school_runtime_allowed(uuid)','EXECUTE'),'Authenticated Data API cannot inspect synthetic admission');
select ok(not has_function_privilege('service_role','internal.synthetic_school_runtime_allowed(uuid)','EXECUTE'),'Service role cannot call synthetic admission');
select ok(not has_function_privilege('cuevo_worker','internal.synthetic_school_runtime_allowed(uuid)','EXECUTE'),'Worker does not gain school membership or population access');
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-000000000001',true);
select is(internal.synthetic_school_runtime_allowed('10000000-0000-4000-8000-000000000001'),false,'Unknown actor never acquires staging school authority');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select is(internal.synthetic_school_runtime_allowed(null),false,'Missing school remains denied');
select is(internal.synthetic_school_runtime_allowed('88000000-0000-4000-8000-000000000099'),false,'Foreign or unknown school remains denied');
select is(internal.synthetic_school_runtime_allowed('10000000-0000-4000-8000-000000000001'),true,'Verified current member may use a populated synthetic school without school GUC');
reset role;
update app.people set synthetic=false where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000013';
set local role cuevo_api;
select is(internal.synthetic_school_runtime_allowed('10000000-0000-4000-8000-000000000001'),false,'Any mixed school person denies the entire staging school');
select is((select count(*)from "authorization".current_memberships() member where member.school_id='10000000-0000-4000-8000-000000000001'and internal.synthetic_school_runtime_allowed(member.school_id)),0::bigint,'Staging membership filtering returns no real school or display names');
reset role;
update app.people set synthetic=true where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000013';
update app.memberships set status='suspended'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000001';
set local role cuevo_api;
select is(internal.synthetic_school_runtime_allowed('10000000-0000-4000-8000-000000000001'),false,'Revoked current membership cannot acquire synthetic authority');
reset role;
update app.memberships set status='active'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000001';
update app.entitlements set enabled=false where school_id='10000000-0000-4000-8000-000000000001'and code='school.context';
set local role cuevo_api;
select is(internal.synthetic_school_runtime_allowed('10000000-0000-4000-8000-000000000001'),false,'Missing school-context entitlement remains denied');
reset role;
update app.entitlements set enabled=true where school_id='10000000-0000-4000-8000-000000000001'and code='school.context';
select is(internal.synthetic_school_runtime_allowed('10000000-0000-4000-8000-000000000001'),true,'Restored synthetic population and current approved membership recover');
insert into app.schools(id,name,country_code)values('88000000-0000-4000-8000-000000000001','Empty staged school','QA');
insert into app.memberships(school_id,actor_id,role,effective_from)values('88000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','admin',clock_timestamp()-interval'1 day');
insert into app.entitlements(school_id,code,enabled,effective_from)values('88000000-0000-4000-8000-000000000001','school.context',true,clock_timestamp()-interval'1 day');
set local role cuevo_api;
select is(internal.synthetic_school_runtime_allowed('88000000-0000-4000-8000-000000000001'),false,'Empty or missing population does not become an allowed school');
reset role;
select *from finish();
rollback;
